def semver_sort(versions):
    def parse_version(v):
        # Split on '+' to remove build metadata
        v_without_build = v.split('+')[0]

        # Split on '-' to separate version from pre-release
        if '-' in v_without_build:
            version_part, prerelease_part = v_without_build.split('-', 1)
        else:
            version_part = v_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = version_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_identifiers = prerelease_part.split('.')
            # Convert identifiers to comparable tuples: (is_numeric, numeric_value or string)
            prerelease_tuple = tuple(
                (True, int(identifier)) if identifier.isdigit() else (False, identifier)
                for identifier in prerelease_identifiers
            )
        else:
            prerelease_tuple = None

        return (major, minor, patch, prerelease_tuple)

    def compare_key(v):
        major, minor, patch, prerelease_tuple = parse_version(v)

        # For sorting:
        # - Compare MAJOR, MINOR, PATCH numerically
        # - Version without pre-release sorts after version with pre-release
        #   (so pre-release tuple should be "smaller" when present)
        # - Pre-release identifiers: all-digit before non-digit, then by value

        if prerelease_tuple is None:
            # No pre-release: sorts after any pre-release of same version
            # Use (major, minor, patch, 1, ()) where 1 indicates "no pre-release"
            return (major, minor, patch, 1, ())
        else:
            # Has pre-release: sorts before any non-pre-release of same version
            # Use (major, minor, patch, 0, prerelease_tuple) where 0 indicates "has pre-release"
            return (major, minor, patch, 0, prerelease_tuple)

    # Sort using the comparison key, maintaining stable sort for equal precedence
    return sorted(versions, key=compare_key)

